{
  "name": "opencode-hooks",
  "version": "1.1.0",
  "description": "OpenCode hooks plugin - all hooks from oh-my-opencode without agents/tools/MCPs",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "type": "module",
  "files": [
    "dist"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target bun --format esm --external @ast-grep/napi && tsc --emitDeclarationOnly",
    "clean": "rm -rf dist",
    "prepublishOnly": "bun run clean && bun run build",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "hooks",
    "claude-code",
    "context-window",
    "session-recovery",
    "think-mode",
    "rules-injector"
  ],
  "author": "Forked from oh-my-opencode by YeonGyu-Kim",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/code-yeongyu/oh-my-opencode"
  },
  "dependencies": {
    "@ast-grep/cli": "^0.40.0",
    "@ast-grep/napi": "^0.40.0",
    "@code-yeongyu/comment-checker": "^0.6.0",
    "picomatch": "^4.0.2",
    "xdg-basedir": "^5.1.0"
  },
  "optionalDependencies": {
    "@opencode-ai/plugin": "^1.0.162"
  },
  "devDependencies": {
    "@types/picomatch": "^3.0.2",
    "bun-types": "latest",
    "typescript": "^5.7.3"
  },
  "trustedDependencies": [
    "@ast-grep/cli",
    "@ast-grep/napi",
    "@code-yeongyu/comment-checker"
  ]
}
